  push(v0, v1) { const n = this.length; if (n === this.cap) this.grow(); this.f0__[n] = v0; this.f0_[n] = v1; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.f0__); this.f0__ = t; t = new Float64Array(cap); t.set(this.f0_); this.f0_ = t; }
